head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.vBzTpCd;
scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vBzTpCd = parentWin.fn_getbzTpCd();
        await scwin.coListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Dscl_onclick
 * @description 「안내문작성」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function() {
    try {
        await scwin.dscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.btn_Dscl_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_CoList_OnClick
 * @description grd_CoList 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_CoList_OnClick = async function(row, colid) {
    try {
        await scwin.isuListSync(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.grd_CoList_OnClick" });
    }
};

/**
 * @method
 * @name dts_CoList_OnLoadError
 * @description dts_CoList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CoList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_CoList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.dts_CoList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_CoList_OnLoadCompleted
 * @description dts_CoList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_CoList_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_IsuList_OnLoadError
 * @description dts_IsuList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsuList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_IsuList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05907.dts_IsuList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IsuList_OnLoadCompleted
 * @description dts_IsuList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuList_OnLoadCompleted = function(rowcount) {
    try {
        edt_IsuTotalCnt.setValue("총 " + dts_IsuList.getRowCount() + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05907.dts_IsuList_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name coListSync
 * @description co List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.coListSync = async function() {
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    const sbmOptions = {
        id : "sbm_dts_CoList",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_CoList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name isuListSync
 * @description isu List Sync 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuListSync = async function(obj) {
    let vIsurCd = dts_CoList.getCellData(Number(obj), "ISUR_CD");
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    url += "&ISUR_CD=" + vIsurCd;
    const sbmOptions = {
        id : "sbm_dts_IsuList",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_IsuList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (dts_IsuList.getRowCount() === 0) {
        await $c.win.alert("[종목현황] 목록에서 선택해주세요");
        return;
    }
    const vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    let vIsurCd = dts_CoList.getCellData(dts_CoList.getRowPosition(), "ISUR_CD");
    const vComNm = dts_CoList.getCellData(dts_CoList.getRowPosition(), "COM_NM");
    const vListDd = dts_CoList.getCellData(dts_CoList.getRowPosition(), "LIST_DD");
    let vDsclTtl;
    let vDsclCtnt;
    let vBzTpNm;
    let vFormCd;
    if (scwin.vBzTpCd === LIST_BZ_TP_CD_003) {
        vBzTpNm = "신규상장";
        vFormCd = "68951";
    } else if (scwin.vBzTpCd === LIST_BZ_TP_CD_005) {
        vBzTpNm = "추가상장";
        vFormCd = "68952";
    }
    const arrPar = new Array();
    for (let i = 1, p = 0; i <= dts_IsuList.getRowCount();
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************
        i++, p++) {
        arrPar[p] = dts_IsuList.getCellData(i, "ISU_ABBRV2");
    }
    const arrIsuStr = $c.elw.fn_getArrIsuNmInfo(arrPar);
    vDsclTtl = "" + vComNm + " (상장일 " + vListDd.substring(0, 4) + "." + vListDd.substring(4, 6) + "." + vListDd.substring(6, 8) + ")" + "";
    vDsclCtnt = vComNm + "가 발행한 주식워런트증권 ";
    // OO증권(주)가 발행한 주식워런트증권 제OOOO호 내지 제OOOO호 00개 종목이 2006년 0월00일 신규상장됩니다.
    vDsclCtnt += "" + arrIsuStr[0].ISUR_STR + " ";
    vDsclCtnt += "총 " + arrIsuStr[0].ISUR_CNT + "개종목이 " + vListDd.substring(0, 4) + "년" + vListDd.substring(4, 6) + "월" + vListDd.substring(6, 8) + "일 " + vBzTpNm + "됩니다.";
    vDsclCtnt += "\r\n";
    vDsclCtnt += "\r\n";
    vDsclCtnt += "기타 자세한 내역은 한국거래소 홈페이지 (http://www.krx.co.kr) 공지사항을 참조하시기 바랍니다.";

    // alert('[vDsclTtl]'+vDsclTtl);
    // alert('[vDsclCtnt]'+vDsclCtnt);
    // alert('[vBzProcsNo]'+vBzProcsNo);
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
     */
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = vFormCd;
        arr[1] = vBzProcsNo; // 테스트할때는 첫번째 업무처리번호를 일단 넘긴다...
        arr[2] = vIsurCd;
        arr[3] = '1';
        arr[4] = vDsclCtnt;
        arr[5] = vDsclTtl;
        $c.stf.copyDataSet(dts_IsuList, param_dts_isu);
        // CopyDataSet( dts_Isu , param_dts_mst) ;
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};
